package com.testora.model;
/** A programming question with judge settings. */
public class Problem implements Comparable<Problem>{ private long id,topicId; private String title,slug,description,difficulty,starterCode,topicName; private int timeLimitSec,maxMarks;
 public Problem(){} public Problem(long id,String title,String slug,String description,String difficulty,String starterCode,long topicId,int limit,int marks){this.id=id;this.title=title;this.slug=slug;this.description=description;this.difficulty=difficulty;this.starterCode=starterCode;this.topicId=topicId;timeLimitSec=limit;maxMarks=marks;}
 public long getId(){return id;} public String getTitle(){return title;} public String getSlug(){return slug;} public String getDescription(){return description;} public String getDifficulty(){return difficulty;} public String getStarterCode(){return starterCode;} public long getTopicId(){return topicId;} public int getTimeLimitSec(){return timeLimitSec;} public int getMaxMarks(){return maxMarks;} public String getTopicName(){return topicName;}
 public void setId(long v){id=v;} public void setTitle(String v){title=v;} public void setSlug(String v){slug=v;} public void setDescription(String v){description=v;} public void setDifficulty(String v){difficulty=v;} public void setStarterCode(String v){starterCode=v;} public void setTopicId(long v){topicId=v;} public void setTimeLimitSec(int v){timeLimitSec=v;} public void setMaxMarks(int v){maxMarks=v;} public void setTopicName(String v){topicName=v;}
 @Override public int compareTo(Problem other){return title.compareToIgnoreCase(other.title);} }
